# Store (light, English), SurfaceStates (the Store page in five states), States (every brick in every state).
from gen import *
W, H = 320, 200

def store_side(active):
    items = [('compass', 'استكشاف', 'Discover', 'discover'), ('installed', 'المثبَّتة', 'Installed', 'installed'), ('update', 'التحديثات', 'Updates', 'updates'), ('package-file', 'تثبيت من ملف', 'Install from a file', 'file'), ('usb', 'مصادر بلا إنترنت', 'Offline sources', 'offline'), ('user', 'الحساب', 'Account', 'account')]
    return sidebar(L('أقسام المتجر', 'Store areas'), ''.join(navitem(i, L(a, e), 'store.area', k == active) for i, a, e, k in items), 60)
begin('Store.dc.html', 'light', False)
CARDS = [('office', 'Office tools', 'Documents, spreadsheets, slides and PDF tools.', True), ('code', 'Coder', 'Code editor with projects, Git and language tools.', True), ('media', 'Media', 'Music, video, photo library and editing.', False), ('mail', 'Communication', 'Mail, calendar, contacts and video calls.', False),
    ('mesh', 'Mesh', 'Link your Ultar devices: screen, files and computing power.', False), ('spark', 'Assistant and local AI', 'Voice assistant and models that run on this device.', True), ('package', 'Linux programs', 'Install .deb packages in an isolated area.', True), ('firefox', 'Firefox', 'Fallback browser. Needs Linux programs.', True),
    ('windows', 'Windows programs', 'Run .exe and .msi programs in an isolated cell.', False), ('android', 'Android apps', 'Run Android apps in a sealed runtime.', False), ('server', 'Containers and server', 'Cells, web administration and SSH server.', False), ('remote', 'Remote access', 'Share your screen or control another one.', False)]
def ccard(icon, name, text, installed):
    state = badge('Installed', 'ok', 'check') if installed else badge('Not installed')
    extra = button('Open', 'store.launch', name='Open ' + name) if installed else ''
    return f'<article style="border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.ctl}; padding: {s3}; box-sizing: border-box; display: flex; flex-direction: column; gap: {s2}"><button{act("store.open", name)} aria-label="{name}: details" style="display: flex; align-items: center; gap: {s3}; border-radius: {r_ctl}"><span style="width: {touch}; height: {touch}; flex: none; border-radius: {r_ctl}; background: {t.raised}; border: {HAIR} solid {t.line}; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center">{ic(icon)}</span><span style="display: block; min-width: 0"><span style="display: block; font-family: {FF_TITLE}; font-weight: {w6}">{name}</span><span style="font-size: {f12}; color: {t.mute}; display: flex; align-items: center; gap: {s1}">{ic("check", True)}KM Code Craft · verified</span></span></button><div style="font-size: {f12}; color: {t.mute}; flex: 1">{text}</div><div style="display: flex; align-items: center; gap: {s2}; min-height: {tgt}">{state}<span style="font-size: {f12}; color: {t.mute}" aria-label="Size not known yet">{NA}</span><span style="flex: 1"></span>{extra}</div></article>'
top = f'<div style="display: flex; align-items: center; gap: {s4}">{h1("Discover")}<span style="flex: 1"></span>{searchbox("Search apps and file types", "store.search", width=g(80))}</div>'
grid = f'<section aria-label="Components by Ultar" style="display: flex; flex-direction: column; gap: {s3}"><div>{h2("Components by Ultar")}{sub("Add or remove parts of the system at any time. Removing a component leaves nothing behind.")}</div><div style="display: grid; grid-template-columns: repeat(4, 1fr); gap: {s3}">{"".join(ccard(*c) for c in CARDS)}</div>{note("— = size comes from the catalogue at run time; the specification defines no value. Install and Remove are on the app page.")}</section>'
out('Ultar Store – discover', W, H, appwindow('Ultar Store', store_side('discover') + f'<main style="flex: 1; min-width: 0; padding: {s5} {s6}; box-sizing: border-box; overflow: hidden; display: flex; flex-direction: column; gap: {s4}">{top}{grid}</main>'), 'Ultar Store · Entdecken · hell · Englisch', 4)

begin('SurfaceStates.dc.html')
def panel(caption, value, body):
    return f'<section aria-label="{plain(caption)}" style="flex: 1; min-width: 0; border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.line}; overflow: hidden; display: flex; flex-direction: column"><div style="padding: {s3} {s4}; background: {t.bar}; border-bottom: {HAIR} solid {t.line}">{h2(caption)}</div><div style="flex: 1; padding: {s4}; display: flex; flex-direction: column; gap: {s3}; min-height: 0">{searchbox("ابحث عن تطبيق أو نوع ملف", "store.search", value=value)}{body}</div></section>'
def inst(icon, name):
    return f'<li style="min-height: {s7}; display: flex; align-items: center; gap: {s3}; border-bottom: {HAIR} solid {t.line}"><span style="display: inline-flex; color: {t.mute}">{ic(icon)}</span><span style="flex: 1">{tx(name)}</span>{button("فتح", "store.launch", "quiet", name="فتح " + name)}</li>'
installed = lambda: f'<div>{h2("المثبَّتة على هذا الجهاز", f14)}<ul role="list">{inst("office", "الأدوات المكتبية")}{inst("code", "المبرمج")}{inst("spark", "المساعد")}</ul></div>'
offl = f'<div style="display: flex; align-items: center; gap: {s3}"><span style="display: inline-flex; color: {t.mute}">{ic("usb")}</span><div style="flex: 1"><div style="font-weight: {w5}">مصادر بلا إنترنت</div>{sub("ذاكرة USB: كتالوج موقَّع")}</div>{button("تصفّح", "store.offline", name="تصفّح المصادر بلا إنترنت")}</div>'
def free(label, on):
    return checkrow(label, 'store.free.item', on, end=f'<span style="font-size: {f12}; color: {t.mute}">{NA}</span>')
p1 = panel('جارٍ التحميل', '', busy('يجري تحميل المتجر…'))
p2 = panel('بحث بلا نتائج', 'جدول المناوبات', empty('search', 'لا نتائج لـ «جدول المناوبات»', 'جرّب اسماً آخر أو نوع ملف مثل ‎.xlsx‎.', button('مسح البحث', 'store.search.clear')))
p3 = panel('غير متصل', '', hint('warn', 'غير متصل بالإنترنت', 'يُعرض ما هو مثبَّت والمصادر بلا إنترنت.', button('إعادة المحاولة', 'store.retry'), icon='offline') + installed() + offl)
p4 = panel('خطأ مع السبب', '', hint('danger', 'تعذّر تحميل المتجر', 'السبب: الخادم ultar.code-craft.tech لم يستجب خلال 30 ثانية.') + f'<div style="display: flex; gap: {s2}">{button("إعادة المحاولة", "store.retry")}{button("حفظ السجلّ", "store.log", "quiet")}</div>' + installed())
p5 = panel('لا مساحة كافية', '', hint('warn', 'لا توجد مساحة كافية لتثبيت «الوسائط»', f'المطلوب: {NA} · المتاح: {NA}') + f'<div>{h2("ما يمكن تحريره", f14)}<div role="group" aria-label="ما يمكن تحريره">{free("سلة المحذوفات", True)}{free("الملفات المؤقتة", True)}{free("تحديثات قديمة", False)}</div></div>' + note('— = تُحسب الأحجام عند التشغيل؛ لا قيمة لها في المواصفة.') + f'<div style="display: flex; gap: {s2}; justify-content: flex-end">{button("إلغاء", "store.free.cancel")}{button("تحرير المساحة والمتابعة", "store.free.go", "primary")}</div>')
out('Ultar Store – حالات الصفحة', 624, 160, f'<div style="position: absolute; inset: 0; padding: {s4}; box-sizing: border-box; display: flex; gap: {s4}">{p1}{p2}{p3}{p4}{p5}</div>', 'Ultar Store · Zustände: lädt, leere Suche, offline, Fehler, zu wenig Platz (§7.3)', 4)

begin('States.dc.html')
STATES = [('', 'عادي'), ('hover', 'تحت المؤشّر'), ('pressed', 'مضغوط'), ('focus', 'عليه التركيز (إطار التركيز)'), ('disabled', 'معطَّل'), ('loading', 'جارٍ التحميل'), ('error', 'خطأ')]
def lrow(state):
    bg = {'hover': t.hover, 'pressed': t.line}.get(state, 'transparent')
    end = ic('ring', True) if state == 'loading' else (ic('error', True, t.danger) if state == 'error' else ic('forward', True))
    return f'<button{act("demo", "صفّ قائمة")} aria-label="صفّ قائمة"{" aria-disabled=\"true\"" if state == "disabled" else ""} style="width: 100%; min-height: {s7}; padding: {s1} {s3}; box-sizing: border-box; border-radius: {r_ctl}; display: flex; align-items: center; gap: {s3}; background: {bg}; color: {t.ctl if state == "disabled" else t.text}; border: {RING if state == "error" else HAIR} solid {t.danger if state == "error" else t.line}{"; " + FOCUS() if state == "focus" else ""}">{ic("wifi", True)}<span style="flex: 1; display: block"><span style="display: block">KM-Office</span><span style="display: block; font-size: {f12}; color: {t.danger if state == "error" else t.mute}">{"تعذّر الاتصال" if state == "error" else "محفوظة"}</span></span>{end}</button>'
BRICKS = [('زر رئيسي', lambda s: button('احتفاظ', 'demo', 'primary', s)), ('زر عادي', lambda s: button('تراجع', 'demo', 'normal', s)), ('زر هادئ', lambda s: button('مسح الكل', 'demo', 'quiet', s)), ('زر خطر', lambda s: button('حذف الحساب', 'demo', 'danger', s)),
    ('زر أيقونة', lambda s: ibtn('الإعدادات', 'gear', 'demo', state=s)), ('مفتاح (مُطفأ)', lambda s: switch(False, 'بلوتوث', 'demo', s)), ('مفتاح (مفعّل)', lambda s: switch(True, 'واي فاي', 'demo', s)), ('قائمة اختيار', lambda s: select('60 Hz', 'معدّل التحديث', 'demo', s)),
    ('شريط الضبط', lambda s: slider('السطوع', 60, 'demo', s)), ('حقل نصّ', lambda s: field('اسم الجهاز', 'demo', value='ultar-pc', state=s, error='الاسم مستخدَم على هذه الشبكة.' if s == 'error' else '', direction='ltr')), ('مربّع اختيار', lambda s: checkrow('الوسائط', 'demo', True, state=s)), ('صفّ قائمة', lrow)]
cell = lambda inner, head=False: f'<div role="{"columnheader" if head else "cell"}" style="padding: {s3}; display: flex; align-items: center; justify-content: center; border-bottom: {HAIR} solid {t.line}; border-inline-start: {HAIR} solid {t.line}; min-height: {g(18)}; box-sizing: border-box{"; font-weight: " + str(w6) + "; background: " + t.bar if head else ""}">{inner}</div>'
rows = f'<div role="row" style="display: contents">{cell("العنصر", True)}{"".join(cell(tx(n), True) for _, n in STATES)}</div>'
for name, fn in BRICKS:
    rows += f'<div role="row" style="display: contents">{cell(tx(name), True)}{"".join(cell(fn(s)) for s, _ in STATES)}</div>'
legend = note('القيم كلها من tokens.toml. لا توجد بعدُ رموز لحالات «تحت المؤشّر/مضغوط/معطَّل» ولا للون إطار التركيز: استُخدمت هنا الأدوار hover و line و control_border و info (انظر REVIEW-SELF.md، اقتراح [state]).')
out('Ultar OS – حالات عناصر الواجهة', 440, 296, f'<main style="position: absolute; inset: 0; padding: {s5}; box-sizing: border-box; display: flex; flex-direction: column; gap: {s4}"><div>{h1("حالات عناصر الواجهة")}{sub("كل عنصر في حالاته السبع (المواصفة، القسم 3).")}</div><div role="table" aria-label="حالات العناصر" style="display: grid; grid-template-columns: {g(40)} repeat(7, 1fr); border-radius: {r_card}; background: {t.surface}; border: {HAIR} solid {t.line}; overflow: hidden">{rows}</div>{legend}</main>', 'Zustände der Bausteine: normal, schwebend, gedrückt, fokussiert, deaktiviert, lädt, Fehler', 4)
